__factories["MachineNavigation.luau"] = function(__require)
--!nocheck
-- Walk to loaded interaction pads; no teleporting, remotes or range spoofing.
local Config = __require("Config.luau")
local Navigation = {}
Navigation.__index = Navigation

local ARRIVAL_DISTANCE = 8
local WAYPOINT_DISTANCE = 4

local function finite(value)
    return type(value) == "number" and value == value and math.abs(value) < math.huge
end

local function position(value)
    return typeof(value) == "Vector3" and finite(value.X) and finite(value.Y) and finite(value.Z)
end

local function child(parent, name)
    return parent and parent:FindFirstChild(name)
end

function Navigation.new(player, onProgress)
    return setmetatable({ Player = player, OnProgress = onProgress, _generation = 0 }, Navigation)
end

function Navigation:_progress(message)
    self.Stage = message
    if type(self.OnProgress) == "function" then pcall(self.OnProgress, message) end
end

function Navigation:_halt(state)
    if not state or not state.moving then return end
    state.moving = false
    local character = self.Player.Character
    if character ~= state.character or not character.Parent or state.humanoid.Parent ~= character
        or character:FindFirstChildOfClass("Humanoid") ~= state.humanoid then return end
    -- A rig may replace its root without replacing the character/humanoid.
    -- Halt at the current root, never drive that rig toward a captured old part.
    local root = child(character, "HumanoidRootPart")
    if not root or not root:IsA("BasePart") or root.Parent ~= character or not position(root.Position) then return end
    pcall(function() state.humanoid:MoveTo(root.Position) end)
end

function Navigation:Stop()
    self._generation += 1
    local state = self._state
    self._state = nil
    self:_halt(state)
end

function Navigation:Approach(variant, active)
    if active and not active() then return false end
    local names = { Gold = "Gold Machine", Rainbow = "Rainbow Machine" }
    local name = names[variant]
    if not name then error("Choose Gold or Rainbow machine navigation.", 0) end
    local map = workspace:FindFirstChild("__MAP")
    local interactive = child(map, "Interactive")
    local machine = child(interactive, name)
    local pad = child(machine, "Pad")
    if not machine or not machine:IsA("Model") or not pad or not pad:IsA("BasePart") or not position(pad.Position) then
        error(name .. " has no loaded __MAP.Interactive model with a Pad part. Enter its world and load the machine normally.", 0)
    end
    local target = pad.Position
    return self:_walk(name, target, function()
        return workspace:FindFirstChild("__MAP") == map and map.Parent ~= nil
            and child(map, "Interactive") == interactive and interactive.Parent == map
            and child(interactive, name) == machine and machine.Parent == interactive
            and child(machine, "Pad") == pad and pad.Parent == machine and position(pad.Position)
            and (pad.Position - target).Magnitude <= 0.1
    end, active)
end

function Navigation:ApproachEgg(model, active)
    if active and not active() then return false end
    if typeof(model) ~= "Instance" or not model:IsA("Model") or not model:IsDescendantOf(workspace) then
        error("The selected egg is not a loaded workspace Model. Enter its world and load it normally.", 0)
    end
    local center = child(model, "Center")
    if not center or not center:IsA("BasePart") or not position(center.Position) then
        error("The selected egg has no loaded Center part with a readable position.", 0)
    end
    local target = center.Position
    local eggId = model:GetAttribute("ID")
    local name = "egg " .. model.Name
    return self:_walk(name, target, function()
        return model:IsDescendantOf(workspace) and model:GetAttribute("ID") == eggId and child(model, "Center") == center
            and center.Parent == model and position(center.Position)
            and (center.Position - target).Magnitude <= 0.1
    end, active)
end

function Navigation:_walk(name, target, stillLoaded, active)
    if active and not active() then return false end
    if self._owner and coroutine.status(self._owner) == "dead" then
        self:_halt(self._state)
        self._state, self._owner = nil, nil
    end
    if self._owner then error("A previous machine walk is still returning; no overlapping walk started.", 0) end
    local character = self.Player.Character
    local root = child(character, "HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not character or not character.Parent or not root or not root:IsA("BasePart") or not position(root.Position)
        or not humanoid or not finite(humanoid.Health) or humanoid.Health <= 0 then
        error("A living character with HumanoidRootPart is required to walk to an interaction.", 0)
    end
    local generation = self._generation
    local owner = coroutine.running()
    local state = { character = character, root = root, humanoid = humanoid, moving = false }
    local timeout = if finite(Config.TravelTimeout) and Config.TravelTimeout > 0 then Config.TravelTimeout else 60
    local deadline = os.clock() + timeout
    self._state, self._owner = state, owner

    local function current()
        if self._generation ~= generation or self._state ~= state or self.Player.Character ~= character
            or not character.Parent or root.Parent ~= character or humanoid.Parent ~= character
            or child(character, "HumanoidRootPart") ~= root or character:FindFirstChildOfClass("Humanoid") ~= humanoid
            or not finite(humanoid.Health) or humanoid.Health <= 0 or (active and not active()) then return false end
        if not stillLoaded() then
            error(name .. " moved or unloaded while walking; no interaction request should be sent.", 0)
        end
        if not position(root.Position) then error("Character position became unreadable while walking.", 0) end
        if os.clock() >= deadline then error("Walking to " .. name .. " timed out before verified arrival.", 0) end
        return true
    end

    -- Remains usable after walking releases its owner/state. It intentionally
    -- does not call active(): the caller's token may include this guard.
    local function arrivalGuard()
        if self._generation ~= generation or self.Player.Character ~= character or not character.Parent
            or root.Parent ~= character or humanoid.Parent ~= character
            or child(character, "HumanoidRootPart") ~= root or character:FindFirstChildOfClass("Humanoid") ~= humanoid
            or not finite(humanoid.Health) or humanoid.Health <= 0 or not position(root.Position) then return false end
        return stillLoaded() and (root.Position - target).Magnitude <= ARRIVAL_DISTANCE
    end

    local ok, result = pcall(function()
        if not current() then return false end
        if (root.Position - target).Magnitude <= ARRIVAL_DISTANCE then return true end
        self:_progress("Finding a walking path to " .. name .. "...")
        if not current() then return false end
        local service = game:GetService("PathfindingService")
        local path = service:CreatePath({ AgentCanJump = true, WaypointSpacing = 4 })
        if not current() then return false end
        path:ComputeAsync(root.Position, target)
        if not current() then return false end
        if path.Status ~= Enum.PathStatus.Success then
            error("No walkable path to " .. name .. ". Move nearer or enter the correct unlocked area, then retry.", 0)
        end
        local waypoints = path:GetWaypoints()
        if not current() then return false end
        if type(waypoints) ~= "table" or #waypoints == 0 then error("Pathfinding returned no walking waypoints.", 0) end
        for _, waypoint in ipairs(waypoints) do
            if not current() then return false end
            if (root.Position - target).Magnitude <= ARRIVAL_DISTANCE then break end
            if not position(waypoint.Position) then error("Pathfinding returned an unreadable waypoint.", 0) end
            -- A nearby jump can still be required to clear the next obstacle.
            if (root.Position - waypoint.Position).Magnitude <= WAYPOINT_DISTANCE
                and waypoint.Action ~= Enum.PathWaypointAction.Jump then continue end
            self:_progress("Walking to " .. name .. " (" .. tostring(math.ceil((root.Position - target).Magnitude)) .. " studs)...")
            if not current() then return false end
            if waypoint.Action == Enum.PathWaypointAction.Jump then humanoid.Jump = true end
            state.moving = true
            humanoid:MoveTo(waypoint.Position)
            while true do
                if not current() then return false end
                if (root.Position - target).Magnitude <= ARRIVAL_DISTANCE
                    or (root.Position - waypoint.Position).Magnitude <= WAYPOINT_DISTANCE then break end
                task.wait(0.1)
            end
        end
        if not current() then return false end
        if (root.Position - target).Magnitude > ARRIVAL_DISTANCE then
            error("Walking ended too far from " .. name .. "; no interaction request should be sent.", 0)
        end
        self:_progress("Arrived near " .. name .. "; checking interaction eligibility.")
        if not current() then return false end
        return (root.Position - target).Magnitude <= ARRIVAL_DISTANCE
    end)
    -- Only this state's movement may be halted; a stale walk cannot stop a newer one.
    self:_halt(state)
    if self._state == state then self._state = nil end
    if self._owner == owner then self._owner = nil end
    if not ok then error(result, 0) end
    return result, if result == true then arrivalGuard else nil
end

return Navigation
end
end

do
__factories["PetCare.luau"] = function(__require)
--!nocheck
-- Native public-library integration. Legacy signatures are not live-event proof.
local Config = __require("Config.luau")
local ConversionPolicy = __require("ConversionPolicy.luau")
local PetCare = {}
PetCare.__index = PetCare

local function none()
    return { AutoHatch = false, AutoGold = false, AutoRainbow = false }
end
local function text(value) return type(value) == "string" and value:match("%S") ~= nil end
local function number(value) return type(value) == "number" and value == value and math.abs(value) < math.huge end
local function child(parent, name) return parent and parent:FindFirstChild(name) end
local function samePlace() return game.PlaceId == Config.Target.PlaceId and game.GameId == Config.Target.UniverseId end

function PetCare.new()
    return setmetatable({ Supported = none(), Reason = "Pet tools idle — click Load pet tools.",
        Report = "Pet tools not loaded.", Counts = { HatchRequests = 0, GoldRequests = 0, RainbowRequests = 0 },
        _generation = 0, _destroyed = false, _reserved = {}, _menus = {} }, PetCare)
end

function PetCare:_report()
    self.Report = "Pet stage: " .. tostring(self._phase or "not started") .. "\nPet tools: " .. self.Reason .. "\nPet-tool loader: " .. (self._loader or "not selected")
        .. "\nPet-tool provider: ReplicatedStorage.Library (public). Legacy commands; current game acceptance unverified."
        .. "\nConversion: exactly six; explicit species; loaded unlocked inventory slots required."
        .. "\nRequests are counted, not confirmed hatches or conversion rewards."
end

function PetCare:_occupied()
    if self._busy and coroutine.status(self._busy) == "dead" then self._busy = nil end
    return self._busy ~= nil
end

function PetCare:Connect(active)
    if self:_occupied() then error("A pet-tool operation is still returning. Stop it and wait before loading again.", 0) end
    if active and not active() then return self end
    self._generation += 1
    local generation = self._generation
    local function current() return self._generation == generation and not self._destroyed and (not active or active()) end
    self.Supported, self._api = none(), nil
    self._phase = "Checking game and public Library"
    self:_report()
    local ok, message = pcall(function()
        if self._destroyed then error("Pet tools unloaded.", 0) end
        if not samePlace() then error("Load pet tools inside the Classic Event destination.", 0) end
        local library = game:GetService("ReplicatedStorage"):FindFirstChild("Library")
        if not library or not library:IsA("ModuleScript") then error("Public Library ModuleScript is not loaded.", 0) end
        local loader, loaderName = require, "require"
        if type(getrenv) == "function" then
            local available, environment = pcall(getrenv)
            if available and type(environment) == "table" and type(environment.require) == "function" then
                loader, loaderName = environment.require, "getrenv().require"
            end
        end
        if not current() then return end
        self._loader = loaderName
        self._phase = "Loading pet API facade"
        self:_report()
        local facade = loader(library)
        if not current() then return end
        if type(facade) ~= "table" then error("Public Library did not return a table.", 0) end
        self._phase = "Reading public Library.Network"
        self:_report()
        local network = facade.Network
        if not current() then return end
        local invoke = type(network) == "table" and network.Invoke
        if not current() then return end
        self._phase = "Reading public Library.Save"
        self:_report()
        local save = facade.Save
        if not current() then return end
        local getSave = type(save) == "table" and save.Get
        if not current() then return end
        self._phase = "Reading public Library.PetCmds"
        self:_report()
        local pets = facade.PetCmds
        if not current() then return end
        local getEquipped = type(pets) == "table" and pets.GetEquipped
        if not current() then return end
        self._phase = "Reading public Library.Directory"
        self:_report()
        local directory = facade.Directory
        if not current() then return end
        local eggDirectory = type(directory) == "table" and directory.Eggs
        if not current() then return end
        local petDirectory = type(directory) == "table" and directory.Pets
        if not current() then return end
        if type(invoke) ~= "function" or type(getSave) ~= "function" then
            error("Public Network.Invoke / Save.Get unavailable. No private networking fallback attempted.", 0)
        end
        self._phase = "Pet API exports validated"
        self:_report()
        self._api = { invoke = invoke, getSave = getSave, getEquipped = getEquipped,
            eggs = eggDirectory, pets = petDirectory, facade = facade }
        self._loader = loaderName
        self.Supported.AutoHatch = type(eggDirectory) == "table"
        local conversion = type(petDirectory) == "table" and type(getEquipped) == "function"
        self.Supported.AutoGold, self.Supported.AutoRainbow = conversion, conversion
        self.Reason = "Pet APIs loaded; no remote probe sent. Server decides access, hatch modes and conversion chances."
    end)
    if not current() then return self end
    if not ok then self.Reason = tostring(message) end
    self:_report()
    return self
end

function PetCare:_run(key, active, work)
    if active and not active() then return 0 end
    if self._destroyed or not samePlace() or not self._api or not self.Supported[key] then error(self.Reason, 0) end
    if self:_occupied() then error("Another pet operation is still returning; no overlapping request sent.", 0) end
    local generation = self._generation
    local function current() return not self._destroyed and generation == self._generation and samePlace() and (not active or active()) end
    local owner = coroutine.running()
    self._busy = owner
    local ok, result = pcall(work, current)
    if self._busy == owner then self._busy = nil end
    if not current() then return 0 end
    if not ok then error(result, 0) end
    return result
end

function PetCare:_request(key, command, counter, current, ...)
    if not current() then return 0 end
    self._lastFailure = nil
    self._phase = "Waiting for " .. command .. " acknowledgement"
    self:_report()
    self.Counts[counter] += 1
    local response = table.pack(pcall(self._api.invoke, command, ...))
    if not current() then return 0 end
    self._phase = "Validating " .. command .. " reply"
    self:_report()
    if not response[1] or response.n < 2 or response[2] ~= true then
        local message
        if not response[1] then message = tostring(response[2])
        elseif response[2] == false and type(response[3]) == "string" then message = response[3] end
        if message then message = message:sub(1, 500):gsub("[%c]", " ") end
        local distance = response[1] and response[2] == false and message
            and message:lower():find("too far", 1, true) ~= nil
        self._lastFailure = if distance then "Distance" else "Unknown"
        -- A definite range rejection is recoverable after approaching normally.
        self.Supported[key] = distance == true
        self.Reason = command .. ": " .. (message or "No true acknowledgement returned.")
            .. (if distance then " Move closer to the target in game, then retry. No automatic retry was sent."
                else " Feature stopped; inspect the error before loading again.")
        self:_report()
        error(self.Reason, 0)
    end
    self.Reason = command .. " acknowledged. Request count does not confirm the resulting pets."
    self:_report()
    return 1
end

function PetCare:_hatchPlan(eggName, mode, current)
    if not text(eggName) then error("Enter an exact egg directory name first.", 0) end
    local count = if mode == "Single" then 1 elseif mode == "Triple" then 3 elseif mode == "Octuple" then 8 else nil
    if not count then error("Choose Single, Triple or Octuple hatch mode.", 0) end
    local egg = self._api.eggs[eggName]
    if not current() then return nil end
    if type(egg) ~= "table" or egg.hatchable ~= true or egg.disabled or egg.isPremium
        or not text(egg.currency) or egg.currency:lower() == "robux" or not number(egg.cost) or egg.cost <= 0 then
        error("Unknown, unavailable or premium egg. Select a hatchable in-game currency egg.", 0)
    end
    self._phase = "Reading hatch balance via Save.Get"
    self:_report()
    local save = self._api.getSave()
    if not current() then return nil end
    if type(save) ~= "table" or not number(save[egg.currency]) then
        error("Unreadable " .. egg.currency .. " balance for this hatch mode.", 0)
    end
    if save[egg.currency] < egg.cost * count then
        self._phase = "Waiting for hatch currency"
        self.Reason = "Waiting for " .. tostring(egg.cost * count) .. " " .. egg.currency .. " at the egg directory price."
        self:_report()
        return nil
    end
    return { Count = count }
end

function PetCare:CanHatch(eggName, mode, active)
    local ready = self:_run("AutoHatch", active, function(current)
        return self:_hatchPlan(eggName, mode, current) ~= nil and current()
    end)
    return ready == true
end

function PetCare:GetEggTarget(eggName, active)
    local result = self:_run("AutoHatch", active, function(current)
        if not text(eggName) or type(self._api.eggs[eggName]) ~= "table" then error("Select an exact egg directory name first.", 0) end
        if not current() then return nil end
        self._phase = "Reading public Library.WorldCmds for loaded eggs"
        self:_report()
        local available, world = pcall(function() return self._api.facade.WorldCmds end)
        if not current() then return nil end
        local getEggs = available and type(world) == "table" and world.GetAllEggs
        if not current() then return nil end
        if type(getEggs) ~= "function" then
            error("Public WorldCmds.GetAllEggs is unavailable. Use Egg travel Off and approach the egg manually.", 0)
        end
        self._phase = "Reading loaded eggs via WorldCmds.GetAllEggs"
        self:_report()
        local eggs = getEggs()
        if not current() then return nil end
        if type(eggs) ~= "table" then error("GetAllEggs returned an unsupported list.", 0) end
        local selected
        for _, model in pairs(eggs) do
            if typeof(model) ~= "Instance" or not model:IsA("Model") then error("GetAllEggs contains an unknown entry.", 0) end
            if model:GetAttribute("ID") == eggName and model:IsDescendantOf(workspace) then
                if selected then error("Multiple loaded egg models share this ID; approach the exact egg manually with Egg travel Off.", 0) end
                selected = model
            end
        end
        if not current() then return nil end
        if not selected then error("Selected egg is not loaded in this world. Enter its unlocked area normally, then retry.", 0) end
        return selected
    end)
    return if result == 0 then nil else result
end

function PetCare:Hatch(eggName, mode, active)
    return self:_run("AutoHatch", active, function(current)
        if not self:_hatchPlan(eggName, mode, current) or not current() then return 0 end
        return self:_request("AutoHatch", "Buy Egg", "HatchRequests", current, eggName, mode == "Triple", mode == "Octuple")
    end)
end

local function speciesId(directory, selected)
    if not text(selected) then error("Choose one conversion species by exact name or ID first.", 0) end
    if type(directory[selected]) == "table" then return selected, directory[selected] end
    local numeric = tonumber(selected)
    if numeric and type(directory[numeric]) == "table" then return tostring(numeric), directory[numeric] end
    local found
    for id, definition in pairs(directory) do
        if type(definition) == "table" and type(definition.name) == "string" and definition.name:lower() == selected:lower() then
            if found then error("Species name is ambiguous; enter its exact directory ID.", 0) end
            found = tostring(id)
        end
    end
    if not found then error("No pet directory entry matches this species.", 0) end
    return found, directory[found] or directory[tonumber(found)]
end

function PetCare:NextChoice(kind, previous)
    if self._destroyed or not samePlace() or not self._api then error("Load pet tools first.", 0) end
    local choices = {}
    local directory = if kind == "Egg" then self._api.eggs elseif kind == "Species" then self._api.pets else nil
    if type(directory) ~= "table" then error("This directory is unavailable.", 0) end
    for id, definition in pairs(directory) do
        if type(definition) ~= "table" then continue end
        local eligible
        if kind == "Egg" then
            eligible = definition.hatchable == true and not definition.disabled and not definition.isPremium
                and text(definition.currency) and definition.currency:lower() ~= "robux" and number(definition.cost) and definition.cost > 0
        else
            eligible = text(definition.rarity) and not definition.isPremium and not definition.isGift and not definition.huge and not definition.titanic
                and definition.rarity ~= "Exclusive" and definition.rarity ~= "Event"
        end
        if eligible and (text(id) or number(id)) then
            table.insert(choices, { value = tostring(id), label = if kind == "Species" and text(definition.name)
                then definition.name .. " (" .. tostring(id) .. ")" else tostring(id) })
        end
    end
    table.sort(choices, function(a, b) return a.value < b.value end)
    if #choices == 0 then error("No eligible entries are loaded in this directory.", 0) end
    local index = 0
    for i, choice in ipairs(choices) do if choice.value == previous then index = i; break end end
    local nextChoice = choices[index % #choices + 1]
    return nextChoice.value, nextChoice.label
end

local function unlockedSlot(playerGui, uid)
    local slots = child(child(child(child(playerGui, "Inventory"), "Frame"), "Main"), "Pets")
    local normal = child(slots, "Normal")
    local slot = child(normal, uid)
    local locked = child(slot, "Locked")
    if not slot or not slot:IsA("TextButton") or not locked or locked.Visible ~= false then return false end
    local favorite = child(slot, "Favorite") or child(slot, "Favourite")
    return not favorite or favorite.Visible == false
end

function PetCare:_conversionBatch(variant, selected, current)
    local id, definition = speciesId(self._api.pets, selected)
    if not current() then return nil end
    if type(definition) ~= "table" or not text(definition.rarity) then error("Unknown species metadata.", 0) end
    local premium = definition.isPremium or definition.isGift or definition.huge or definition.titanic
        or definition.rarity == "Exclusive" or definition.rarity == "Event"
    self._phase = "Reading conversion inventory via Save.Get"
    self:_report()
    local save = self._api.getSave()
    if not current() then return nil end
    if type(save) ~= "table" or type(save.Pets) ~= "table" then error("Save.Get did not provide a Pets table.", 0) end
    self._phase = "Reading equipped pets via PetCmds.GetEquipped"
    self:_report()
    local equipped = self._api.getEquipped()
    if not current() then return nil end
    if type(equipped) ~= "table" then error("Equipped pet records are unreadable; conversion stopped.", 0) end
    local worn = {}
    for _, pet in pairs(equipped) do
        if type(pet) ~= "table" or not text(pet.uid) then error("Unknown equipped-pet schema.", 0) end
        worn[pet.uid] = true
    end
    local normalized, present = {}, {}
    local player = game:GetService("Players").LocalPlayer
    local gui = player and player:FindFirstChild("PlayerGui")
    for _, pet in pairs(save.Pets) do
        if type(pet) ~= "table" or not text(pet.uid) or (type(pet.id) ~= "string" and type(pet.id) ~= "number") then
            error("Unknown inventory pet schema; no conversion sent.", 0)
        end
        present[pet.uid] = true
        local protected = premium or self._reserved[pet.uid] or false
        for _, flag in ipairs({ "g", "r", "dm", "hc", "sh", "l", "lk", "locked", "favorite", "fav" }) do
            if pet[flag] ~= nil and type(pet[flag]) ~= "boolean" then protected = true end
        end
        protected = protected or pet.dm or pet.hc or pet.sh or pet.l or pet.lk or pet.locked or pet.favorite or pet.fav
            or (text(pet.nk)) or (type(pet.e) == "table" and next(pet.e) ~= nil)
        local unlocked = unlockedSlot(gui, pet.uid)
        table.insert(normalized, { uid = pet.uid, species = tostring(pet.id),
            variant = if pet.r then "Rainbow" elseif pet.g then "Gold" else "Normal",
            protected = protected == true, equipped = worn[pet.uid] == true,
            eligible = tostring(pet.id) == id and unlocked and not protected })
    end
    if not current() then return nil end
    for uid in pairs(self._reserved) do if not present[uid] then self._reserved[uid] = nil end end
    local batch, reason = ConversionPolicy.NextBatch(normalized, variant)
    if not batch then
        self.Reason = (reason or "No eligible batch.") .. " Open Inventory to load lock indicators; select one species."
        self:_report()
        return nil
    end
    if not current() then return nil end
    return batch
end

function PetCare:CanConvert(variant, selected, active)
    local key = if variant == "Gold" then "AutoGold" elseif variant == "Rainbow" then "AutoRainbow" else nil
    if not key then error("Choose Gold or Rainbow conversion.", 0) end
    local result = self:_run(key, active, function(current)
        local batch = self:_conversionBatch(variant, selected, current)
        return batch ~= nil and current()
    end)
    return result == true
end

function PetCare:Convert(variant, selected, active)
    local key = if variant == "Gold" then "AutoGold" elseif variant == "Rainbow" then "AutoRainbow" else nil
    if not key then error("Choose Gold or Rainbow conversion.", 0) end
    return self:_run(key, active, function(current)
        local batch = self:_conversionBatch(variant, selected, current)
        if not batch or not current() then return 0 end
        -- Reserve before the request: an uncertain/late reply must never replay UIDs.
        for _, uid in ipairs(batch) do self._reserved[uid] = true end
        local ok, result = pcall(self._request, self, key,
            if variant == "Gold" then "Use Golden Machine" else "Use Rainbow Machine",
            if variant == "Gold" then "GoldRequests" else "RainbowRequests", current, batch)
        if not ok then
            if current() and self._lastFailure == "Distance" then
                for _, uid in ipairs(batch) do self._reserved[uid] = nil end
            end
            error(result, 0)
        end
        return result
    end)
end

function PetCare:OpenMenu(kind)
    if self._destroyed then error("Pet tools unloaded.", 0) end
    local names = { Gold = "Golden", Rainbow = "Rainbow", Inventory = "Inventory", Egg = "Eggs" }
    local player = game:GetService("Players").LocalPlayer
    local gui = player and player:FindFirstChild("PlayerGui")
    local menu = names[kind] and child(gui, names[kind])
    if not menu or not menu:IsA("ScreenGui") then error("That native game menu is not loaded. Open it normally once, then retry.", 0) end
    if self._menus[menu] == nil then self._menus[menu] = menu.Enabled end
    menu.Enabled = true
    return true
end

function PetCare:Destroy()
    self._generation += 1
    self._destroyed, self._api, self.Supported = true, nil, none()
    for menu, enabled in pairs(self._menus) do if menu.Parent then pcall(function() menu.Enabled = enabled end) end end
    table.clear(self._menus)
end

return PetCare
end
end

do
__factories["PetSim99.luau"] = function(__require)
--!nocheck
-- Experimental legacy coin protocol; current Classic Event support requires a live probe.
-- Native module access only. No hooks, upvalues, or authentication bypasses.
local PetSim99 = {}
PetSim99.__index = PetSim99
local Config = __require("Config.luau")

local function supportedNone()
    return { AutoFarm = false, AutoCollectOrbs = false, AutoCollectLootbags = false, WalkToTarget = false }
end

local function finite(value)
    return type(value) == "number" and value == value and value > -math.huge and value < math.huge
end

local function identifier(value)
    return (type(value) == "string" and value ~= "") or finite(value)
end

local function vector(value)
    return typeof(value) == "Vector3" and finite(value.X) and finite(value.Y) and finite(value.Z)
end

local function childSummary(parent, limit)
    if not parent then return "not present" end
    local names = {}
    for _, child in ipairs(parent:GetChildren()) do
        table.insert(names, child.Name .. " (" .. child.ClassName .. ")")
    end
    table.sort(names)
    local total = #names
    while #names > limit do table.remove(names) end
    local result = table.concat(names, ", ")
    if total > limit then result ..= string.format(" ... (%d more)", total - limit) end
    return if result == "" then "empty" else result
end

local function selectLoader()
    if type(getrenv) == "function" then
        local ok, environment = pcall(getrenv)
        if ok and type(environment) == "table" and type(environment.require) == "function" then
            return environment.require, "getrenv().require"
        end
    end
    return require, "require"
end

local function requireModule(module, path, loader)
    if not module or not module:IsA("ModuleScript") then
        error(path .. " is not an available ModuleScript. Reconnect after the event finishes loading.", 0)
    end
    local ok, value = pcall(loader or require, module)
    if not ok then
        error("Native require of " .. path .. " failed: " .. tostring(value)
            .. ". Module access may be unsupported by this executor; no bypass is attempted.", 0)
    end
    if type(value) ~= "table" then error(path .. " returned an unsupported value; expected a table.", 0) end
    return value
end

local function responseSummary(result)
    local types = {}
    for index = 1, result.n do table.insert(types, typeof(result[index])) end
    return "returns=" .. tostring(result.n) .. "; types=" .. (if #types > 0 then table.concat(types, ",") else "none")
end

local function exportSummary(exports, expected, active)
    local names = {}
    local keys = {}
    for name, value in pairs(exports) do
        if type(name) == "string" then keys[name] = true end
    end
    for _, name in ipairs(expected or {}) do keys[name] = true end
    for name in pairs(keys) do
        if active and not active() then return nil end
        local readable, value = pcall(function() return exports[name] end)
        if active and not active() then return nil end
        local shape = if readable then typeof(value) else "unavailable"
        if readable and type(value) == "function" and debug and type(debug.info) == "function" then
            local ok, count, variadic = pcall(debug.info, value, "a")
            if ok then shape ..= "(args=" .. tostring(count) .. ",variadic=" .. tostring(variadic) .. ")" end
        end
        table.insert(names, name .. ":" .. shape)
    end
    table.sort(names)
    while #names > 40 do table.remove(names) end
    return table.concat(names, ", ")
end

local function physicalPosition(instance)
    if instance:IsA("BasePart") then return instance.Position end
    if instance:IsA("Model") then
        local part = instance.PrimaryPart or instance:FindFirstChildWhichIsA("BasePart", true)
        if part then return part.Position end
    end
    return nil
end

function PetSim99.new()
    return setmetatable({
        Supported = supportedNone(),
        Reason = "Not connected. Reconnect inside the Classic Event to test the experimental coin protocol.",
        Report = "Not inspected yet.",
        _connected = false, _destroyed = false, _generation = 0,
        _cooldowns = setmetatable({}, { __mode = "k" }), _assigned = {},
        _counts = { FarmDispatches = 0, OrbIds = 0, LootbagIds = 0 },
    }, PetSim99)
end

function PetSim99:_report()
    self.Report = "Probe stage: " .. tostring(self._phase or "not started") .. "\n" .. (self._diagnostics or "Not inspected yet.") .. "\nAdapter: " .. self.Reason
        .. "\nGet Coins response: " .. (self._coinResponse or "not called")
        .. "\nModule loader: " .. (self._loaderName or "not selected")
        .. "\nNetwork provider: " .. (self._networkProvider or "not selected")
        .. "\nNetwork exports: " .. (self._networkExports or "not loaded")
        .. "\nPetCmds exports: " .. (self._petExports or "not loaded")
        .. string.format("\nRequests only: %d pet farm dispatches; %d orb IDs; %d lootbag IDs. No collection/break confirmation is inferred.",
            self._counts.FarmDispatches, self._counts.OrbIds, self._counts.LootbagIds)
end

function PetSim99:_block(message)
    self._connected = false
    self.Supported = supportedNone()
    self.Reason = tostring(message)
    self:_report()
end

function PetSim99:_fail(message)
    self:_block(message)
    error(message, 0)
end

function PetSim99:_root()
    local player = game:GetService("Players").LocalPlayer
    local character = player and player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not root or not root:IsA("BasePart") or not vector(root.Position) then
        error("The character's HumanoidRootPart is unavailable. Wait for respawn and reconnect.", 0)
    end
    return root
end

function PetSim99:_call(method, command, ...)
    local generation = self._generation
    local outcome = table.pack(pcall(self._network[method], command, ...))
    if not outcome[1] then
        error(command .. " failed: " .. tostring(outcome[2])
            .. ". The event protocol or module access may differ; no bypass is attempted.", 0)
    end
    local result = table.pack(table.unpack(outcome, 2, outcome.n))
    if command == "Get Coins" and generation == self._generation and not self._destroyed then
        self._coinResponse = responseSummary(result)
    end
    if result[1] == false then error(command .. " was explicitly rejected by the game.", 0) end
    return table.unpack(result, 1, result.n)
end

function PetSim99:_readSnapshot(probe, active)
    local generation = self._generation
    local function current()
        return generation == self._generation and not self._destroyed and (not active or active())
    end
    if not current() then error("Coin read canceled before networking.", 0) end
    self._phase = "Waiting for Network.Invoke(Get Coins) to return"
    self:_report()
    local returned = table.pack(self:_call("Invoke", "Get Coins"))
    if not current() then error("Coin read canceled by timeout, reconnect or unload.", 0) end
    self._phase = "Validating Get Coins reply"
    self:_report()
    local records = if returned.n == 1 then returned[1] else nil
    -- Status+payload responses must pass the same concrete coin validation.
    if returned.n == 2 and returned[1] == true and type(returned[2]) == "table" then
        records = returned[2]
    end
    local root = self:_root()
    if returned.n == 0 then
        error("Get Coins returned no values (returns=0; types=none). This native route provided no coin data. Inspect Network._check warnings and rejoin before another manual probe.", 0)
    end
    if type(records) ~= "table" then
        error("Get Coins returned an unsupported response (" .. responseSummary(returned)
            .. "); expected a coin dictionary or true plus a coin dictionary. A nil/empty reply does not establish compatibility.", 0)
    end
    if probe and next(records) == nil then
        error("Get Coins returned no records. Stand near loaded Classic Event coins and reconnect.", 0)
    end
    local candidates, assignments = {}, {}
    local allHealthKnown = true
    for id, raw in pairs(records) do
        if not identifier(id) or type(raw) ~= "table" or not vector(raw.p)
            or type(raw.a) ~= "string" or type(raw.n) ~= "string"
            or (raw.health ~= nil and (not finite(raw.health) or raw.health < 0))
            or (raw.h ~= nil and (not finite(raw.h) or raw.h < 0))
            or (raw.health ~= nil and raw.h ~= nil and raw.health ~= raw.h) then
            error("Get Coins returned an unknown coin schema. Farming is disabled rather than guessing a wrapper or field mapping.", 0)
        end
        local instance = self._coins:FindFirstChild(tostring(id))
        local coinPart = instance and instance:FindFirstChild("Coin")
        if not coinPart or not coinPart:IsA("BasePart") then
            coinPart = instance and instance:FindFirstChild("POS")
        end
        local areaAllowed = true
        if self._world and type(self._world.HasArea) == "function" then
            local ok, allowed = pcall(self._world.HasArea, raw.a)
            if not ok then error("WorldCmds.HasArea failed; reconnect before farming: " .. tostring(allowed), 0) end
            areaAllowed = allowed == true
        end
        if instance and instance:IsA("Model") and coinPart and coinPart:IsA("BasePart") and areaAllowed then
            local health = if raw.health ~= nil then raw.health else raw.h
            local healthKnown = health ~= nil
            allHealthKnown = allHealthKnown and healthKnown
            table.insert(candidates, {
                id = id, name = raw.n, area = raw.a,
                health = if healthKnown then health else 1,
                healthKnown = healthKnown,
                distance = (root.Position - raw.p).Magnitude,
                position = raw.p, instance = instance,
            })
            local assigned = {}
            if type(raw.pets) == "table" then
                for _, uid in pairs(raw.pets) do
                    if identifier(uid) then assigned[tostring(uid)] = true end
                end
            end
            assignments[tostring(id)] = assigned
        end
    end
    if probe and #candidates == 0 then
        error("No valid Get Coins record matches a loaded __THINGS.Coins model with a Coin or POS BasePart. Stand near event coins and reconnect.", 0)
    end
    if not current() then error("Pet read canceled before module access.", 0) end
    self._phase = "Reading equipped pets via PetCmds.GetEquipped"
    self:_report()
    local ok, equipped = pcall(self._petCmds.GetEquipped)
    if not current() then error("Pet read canceled by timeout, reconnect or unload.", 0) end
    if not ok then error("PetCmds.GetEquipped failed: " .. tostring(equipped), 0) end
    if type(equipped) ~= "table" then error("PetCmds.GetEquipped returned an unsupported value; expected pet records.", 0) end
    local pets, seen = {}, {}
    for _, pet in pairs(equipped) do
        if type(pet) ~= "table" or not identifier(pet.uid) then
            error("PetCmds.GetEquipped returned an unknown pet record; expected a uid field.", 0)
        end
        local key = tostring(pet.uid)
        if not seen[key] then
            seen[key] = true
            table.insert(pets, pet.uid)
        end
    end
    self._assigned = assignments
    return { Candidates = candidates, Pets = pets, HealthKnown = #candidates > 0 and allHealthKnown }
end

-- Non-invasive preflight. Reads only local objects; no require, Invoke or Fire.
-- A green local check is not proof that the game accepts the coin protocol.
function PetSim99:Inspect()
    local storage = game:GetService("ReplicatedStorage")
    local library = storage:FindFirstChild("Library")
    local client = library and library:FindFirstChild("Client")
    local things = workspace:FindFirstChild("__THINGS")
    local coins = things and things:FindFirstChild("Coins")
    local player = game:GetService("Players").LocalPlayer
    local character = player and player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local issues = {}
    if game.PlaceId ~= Config.Target.PlaceId or game.GameId ~= Config.Target.UniverseId then
        table.insert(issues, "Wrong destination: join the PS99 Classic Event place.")
    end
    if not library or not (library:IsA("ModuleScript") or library:IsA("Folder")) then
        table.insert(issues, "ReplicatedStorage.Library is not loaded.")
    elseif library:IsA("Folder") and not client then
        table.insert(issues, "Legacy Library.Client folder is missing.")
    end
    if not coins or not coins:IsA("Folder") then
        table.insert(issues, "No loaded __THINGS.Coins folder.")
    elseif #coins:GetChildren() == 0 then
        table.insert(issues, "No coin models are loaded nearby.")
    end
    if not root or not root:IsA("BasePart") then
        table.insert(issues, "Character HumanoidRootPart is unavailable.")
    end
    self._diagnostics = table.concat({
        "LOCAL PREFLIGHT (no game modules or network touched)",
        "PlaceId: " .. tostring(game.PlaceId) .. " (expected " .. tostring(Config.Target.PlaceId) .. ")",
        "UniverseId: " .. tostring(game.GameId) .. " (expected " .. tostring(Config.Target.UniverseId) .. ")",
        "Library: " .. (if library then library.ClassName else "missing"),
        "Library.Client: " .. childSummary(client, 50),
        "__THINGS: " .. childSummary(things, 40),
        "Coins: " .. (if coins then tostring(#coins:GetChildren()) else "missing"),
        "Character root: " .. (if root then "present" else "missing"),
        "Preflight issues: " .. (if #issues == 0 then "none" else table.concat(issues, "; ")),
    }, "\n")
    self._phase = "Local preflight finished; no remote request sent"
    self:_report()
    return #issues == 0, if #issues == 0
        then "Local objects present. Run the separate compatibility check to test game protocol."
        else table.concat(issues, "; ")
end

function PetSim99:Connect(active)
    if active and not active() then return self end
    self._generation += 1
    local generation = self._generation
    local function current()
        return generation == self._generation and not self._destroyed and (not active or active())
    end
    self._destroyed, self._connected = false, false
    self.Supported = supportedNone()
    self._network, self._petCmds, self._world, self._coins, self._things = nil, nil, nil, nil, nil
    self._assigned = {}
    self._coinResponse, self._networkExports, self._petExports = nil, nil, nil
    self._moduleLoader, self._loaderName, self._networkProvider = nil, nil, nil
    self._cooldowns = setmetatable({}, { __mode = "k" })
    self._phase = "Inspecting local game environment"
    self._diagnostics = nil
    self:_report()
    local matches = game.PlaceId == Config.Target.PlaceId and game.GameId == Config.Target.UniverseId
    local storage = game:GetService("ReplicatedStorage")
    local library = storage:FindFirstChild("Library")
    local client = library and library:FindFirstChild("Client")
    local things = workspace:FindFirstChild("__THINGS")
    self._diagnostics = table.concat({
        "Target: PS99 Classic Event (not legacy standalone PSX)",
        "PlaceId: " .. tostring(game.PlaceId),
        "UniverseId: " .. tostring(game.GameId),
        "Observed event destination: " .. (if matches then "MATCH" else "DIFFERENT PLACE/UNIVERSE"),
        "ReplicatedStorage: " .. childSummary(storage, 50),
        "Library: " .. childSummary(library, 80),
        "Library.Client: " .. childSummary(client, 120),
        "Framework: " .. childSummary(storage:FindFirstChild("Framework"), 50),
        "Network: " .. childSummary(storage:FindFirstChild("Network"), 100),
        "Workspace: " .. childSummary(workspace, 40),
        "__THINGS: " .. childSummary(things, 60),
        "__DEBRIS: " .. childSummary(workspace:FindFirstChild("__DEBRIS"), 40),
    }, "\n")
    self._phase = "Validating event PlaceId and replicated objects"
    self:_report()
    local ok, message = pcall(function()
        if not matches then
            error("Enter Classic Event place " .. tostring(Config.Target.PlaceId) .. " in universe "
                .. tostring(Config.Target.UniverseId) .. " and reconnect. Current destination differs.", 0)
        end
        if not library then error("ReplicatedStorage.Library is not loaded. Wait inside the event and reconnect.", 0) end
        self._phase = "Choosing native module loader"
        self:_report()
        local loader, loaderName = selectLoader()
        if not current() then return end
        self._moduleLoader, self._loaderName = loader, loaderName
        local network, petCmds, world, networkPath
        if library:IsA("ModuleScript") then
            -- Use the documented public library rather than bypassing its facade.
            self._networkProvider = "ReplicatedStorage.Library"
            networkPath = "ReplicatedStorage.Library.Network"
            self._phase = "Loading ReplicatedStorage.Library ModuleScript"
            self:_report()
            local facade = requireModule(library, "ReplicatedStorage.Library", loader)
            if not current() then return end
            network = facade.Network
            if not current() then return end
            petCmds = facade.PetCmds
            if not current() then return end
            local ok, value = pcall(function() return facade.WorldCmds end)
            if not current() then return end
            if ok then world = value end
            if type(network) ~= "table" or type(petCmds) ~= "table" then
                error("Public ReplicatedStorage.Library facade lacks Network/PetCmds tables. Internal client networking was not retried.", 0)
            end
        else
            -- Compatibility for legacy folder-only layouts; current event has a facade.
            if not client then error("Library.Client is not loaded. Wait inside the event and reconnect.", 0) end
            local networkModule = client:FindFirstChild("Network")
            networkPath = "Library.Client.Network"
            if not networkModule then
                networkModule = library:FindFirstChild("Network")
                networkPath = "Library.Network"
            end
            self._networkProvider = networkPath
            self._phase = "Loading legacy network ModuleScript"
            self:_report()
            network = requireModule(networkModule, networkPath, loader)
            if not current() then return end
            petCmds = requireModule(client:FindFirstChild("PetCmds"), "Library.Client.PetCmds", loader)
            if not current() then return end
            local worldModule = client:FindFirstChild("WorldCmds")
            if worldModule and worldModule:IsA("ModuleScript") then
                local loaded, value = pcall(loader, worldModule)
                if not current() then return end
                if loaded then world = value end
            end
        end
        self._phase = "Inspecting network and pet command exports"
        self:_report()
        local networkExports = exportSummary(network, { "Invoke", "Fire" }, current)
        if not current() then return end
        local petExports = exportSummary(petCmds, { "GetEquipped" }, current)
        if not current() then return end
        local invoke = network.Invoke
        if not current() then return end
        local fire = network.Fire
        if not current() then return end
        if type(invoke) ~= "function" or type(fire) ~= "function" then
            error(networkPath .. " lacks Invoke/Fire functions; this protocol is unsupported.", 0)
        end
        local getEquipped = petCmds.GetEquipped
        if not current() then return end
        if type(getEquipped) ~= "function" then
            error("PetCmds lacks GetEquipped; this protocol is unsupported.", 0)
        end
        local hasArea
        if type(world) == "table" then hasArea = world.HasArea end
        if not current() then return end
        self._network, self._petCmds = network, petCmds
        self._networkExports, self._petExports = networkExports, petExports
        self._things = things
        self._coins = things and things:FindFirstChild("Coins")
        if not self._coins or not self._coins:IsA("Folder") then
            error("__THINGS.Coins is not an available Folder. Enter a loaded coin area and reconnect.", 0)
        end
        if type(hasArea) == "function" then self._world = world end
        self._phase = "Starting Get Coins protocol probe"
        self:_report()
        local snapshot = self:_readSnapshot(true, active)
        if not current() then return end
        self._phase = "Probe succeeded; features can be enabled manually"
        self._connected = true
        self.Supported.AutoFarm, self.Supported.WalkToTarget = true, true
        local orbs = things:FindFirstChild("Orbs")
        local lootbags = things:FindFirstChild("Lootbags")
        self.Supported.AutoCollectOrbs = orbs ~= nil and orbs:IsA("Folder")
        self.Supported.AutoCollectLootbags = lootbags ~= nil and lootbags:IsA("Folder")
        self.Reason = string.format("Experimental legacy protocol probe passed (%d loaded coins, %d equipped pets); Classic Event farming still unverified in game.",
            #snapshot.Candidates, #snapshot.Pets)
    end)
    if not current() then return self end
    if not ok then self:_block(tostring(message)) end
    self:_report()
    return self
end

function PetSim99:Snapshot(active)
    if not self._connected or self._destroyed then error(self.Reason, 0) end
    local generation = self._generation
    local ok, result = pcall(self._readSnapshot, self, false, active)
    if generation ~= self._generation or self._destroyed or (active and not active()) then
        error("Snapshot canceled by timeout, reconnect or unload.", 0)
    end
    if not ok then self:_fail(tostring(result)) end
    return result
end

function PetSim99:Assign(target, pets, active)
    if not self._connected or self._destroyed then error(self.Reason, 0) end
    if type(target) ~= "table" or not identifier(target.id) or not target.instance then
        error("A loaded target from Snapshot is required.", 0)
    end
    local generation = self._generation
    local function current()
        return self._connected and not self._destroyed and generation == self._generation
            and target.instance.Parent == self._coins and (not active or active())
    end
    local count, seen = 0, {}
    local assigned = self._assigned[tostring(target.id)] or {}
    local ok, message = pcall(function()
        for _, uid in ipairs(pets) do
            if not current() then break end
            if not identifier(uid) then error("Equipped pet UID is invalid.", 0) end
            local key = tostring(uid)
            if not seen[key] and not assigned[key] then
                seen[key] = true
                local joined = self:_call("Invoke", "Join Coin", target.id, { uid })
                if not current() then break end
                if joined ~= true then
                    if type(joined) ~= "table" then error("Join Coin returned an unsupported acknowledgement; no Farm Coin request sent.", 0) end
                    local accepted = joined[uid]
                    if accepted == nil and uid ~= key then accepted = joined[key] end
                    if not current() then break end
                    if accepted ~= true then
                        self.Reason = "Join Coin did not accept an equipped pet; no farm request sent for that pet."
                        if type(accepted) == "string" then self.Reason ..= " " .. accepted:sub(1, 300) end
                        continue
                    end
                end
                self:_call("Fire", "Farm Coin", target.id, uid)
                count += 1
                self._counts.FarmDispatches += 1
                assigned[key] = true
                task.wait(0.15)
            end
        end
    end)
    self:_report()
    if not ok and current() then self:_fail(tostring(message)) end
    return count
end

function PetSim99:Collect(kind, radius, active)
    if not self._connected or self._destroyed then error(self.Reason, 0) end
    local folderName, command, limit, supportKey
    if kind == "orbs" then
        folderName, command, limit, supportKey = "Orbs", "Claim Orbs", 20, "AutoCollectOrbs"
    elseif kind == "lootbags" then
        folderName, command, limit, supportKey = "Lootbags", "Collect Lootbag", 4, "AutoCollectLootbags"
    else error("Unknown pickup kind; expected orbs or lootbags.", 0) end
    if not self.Supported[supportKey] then error(folderName .. " collection is unavailable.", 0) end
    if not finite(radius) then error("Pickup radius must be a finite number.", 0) end
    radius = math.clamp(radius, 0, 30)
    local generation = self._generation
    local function current()
        return self._connected and not self._destroyed and generation == self._generation and (not active or active())
    end
    local count = 0
    local ok, message = pcall(function()
        local folder = self._things:FindFirstChild(folderName)
        if not folder or not folder:IsA("Folder") then error(folderName .. " is no longer loaded. Reconnect.", 0) end
        local root = self:_root()
        local ids, objects, seen = {}, {}, {}
        for _, object in ipairs(folder:GetChildren()) do
            if not current() or #ids >= limit then break end
            local position = physicalPosition(object)
            local eligibleAt = self._cooldowns[object] or -math.huge
            if object.Parent == folder and vector(position) and (root.Position - position).Magnitude <= radius
                and os.clock() - eligibleAt >= 2 and object:GetAttribute("Collected") ~= true
                and object.Name ~= "" and not seen[object.Name] then
                seen[object.Name] = true
                table.insert(ids, object.Name)
                table.insert(objects, object)
            end
        end
        if #ids == 0 or not current() then return end
        if kind == "orbs" then
            self:_call("Fire", command, ids)
            count = #ids
            self._counts.OrbIds += count
            for _, object in ipairs(objects) do self._cooldowns[object] = os.clock() end
        else
            for index, object in ipairs(objects) do
                if not current() then break end
                root = self:_root()
                local position = physicalPosition(object)
                if object.Parent == folder and vector(position) and (root.Position - position).Magnitude <= radius then
                    self:_call("Fire", command, ids[index], root.Position)
                    self._cooldowns[object] = os.clock()
                    count += 1
                    self._counts.LootbagIds += 1
                    task.wait(0.15)
                end
            end
        end
    end)
    self:_report()
    if not ok and current() then self:_fail(tostring(message)) end
    return count
end

function PetSim99:Destroy()
    self._generation += 1
    self._destroyed = true
    self:_block("Adapter unloaded.")
    self._network, self._petCmds, self._world, self._coins, self._things = nil, nil, nil, nil, nil
    self._assigned = {}
    self._cooldowns = setmetatable({}, { __mode = "k" })
end

return PetSim99
end
end

do
__factories["Policy.luau"] = function(__require)
--!strict
-- Pure targeting and settings rules; also executed by the standalone Luau tests.
local Policy = {}

local numeric = {
    Radius = { 10, 1000 },
    FarmInterval = { 0.25, 10 },
    WalkSpeed = { 8, 100 },
    JumpPower = { 0, 150 },
    HatchInterval = { 1, 30 },
    ConversionInterval = { 2, 30 },
}
local booleans = {
    AutoFarm = true,
    AutoCollectOrbs = true,
    AutoCollectLootbags = true,
    WalkToTarget = true,
    MovementEnabled = true,
    Fullbright = true,
    AntiIdle = true,
    AutoHatch = true,
    AutoGold = true,
    AutoRainbow = true,
}

function Policy.option(key: string, value: any): (any, string?)
    if booleans[key] then
        if type(value) == "boolean" then
            return value, nil
        end
        return nil, "Expected an on/off value."
    end
    local range = numeric[key]
    if range then
        local number = tonumber(value)
        if not number or number ~= number or math.abs(number) == math.huge then
            return nil, "Enter a finite number."
        end
        return math.clamp(number, range[1], range[2]), nil
    end
    if key == "FarmMode" then
        if value == "Nearest" or value == "Weakest" or value == "Strongest" then
            return value, nil
        end
        return nil, "Unknown farm mode."
    end
    if key == "HatchMode" then
        if value == "Single" or value == "Triple" or value == "Octuple" then return value, nil end
        return nil, "Choose Single, Triple or Octuple."
    end
    if key == "MachineTravelMode" or key == "EggTravelMode" then
        if value == "Walk" or value == "Off" then return value, nil end
        return nil, "Choose Walk or Off for travel."
    end
    if key == "Area" or key == "NameFilter" or key == "EggName" or key == "ConversionSpecies" then
        if type(value) ~= "string" then
            return nil, "Expected text."
        end
        local text = string.sub(value, 1, 100):match("^%s*(.-)%s*$") or ""
        if key == "Area" and text == "" then
            text = "All"
        end
        return text, nil
    end
    return nil, "Unknown setting: " .. tostring(key)
end

function Policy.select(candidates: { any }, options: any): any
    local selected = nil
    local filter = string.lower(options.NameFilter)
    local area = string.lower(options.Area)
    for _, item in ipairs(candidates) do
        local valid = item.health > 0
            and item.distance <= options.Radius
            and (area == "all" or string.lower(item.area) == area)
            and (filter == "" or string.find(string.lower(item.name), filter, 1, true) ~= nil)
        if not valid then
            continue
        end
        local better = selected == nil
        if selected then
            if options.FarmMode == "Weakest" and item.health ~= selected.health then
                better = item.health < selected.health
            elseif options.FarmMode == "Strongest" and item.health ~= selected.health then
                better = item.health > selected.health
            elseif item.distance ~= selected.distance then
                better = item.distance < selected.distance
            else
                better = tostring(item.id) < tostring(selected.id)
            end
        end
        if better then
            selected = item
        end
    end
    return selected
end

return Policy
end
end

do
__factories["Runtime.luau"] = function(__require)
--!nocheck
local Config = __require("Config.luau")
local Policy = __require("Policy.luau")
local Jobs = __require("Jobs.luau")
local Interface = __require("Interface.luau")
local PetSim99 = __require("PetSim99.luau")
local PetCare = __require("PetCare.luau")
local MachineNavigation = __require("MachineNavigation.luau")

local Lighting = game:GetService("Lighting")
local HttpService = game:GetService("HttpService")
local Runtime = {}
Runtime.__index = Runtime

function Runtime.new(player, parent)
    local self = setmetatable({
        Player = player, Alive = true, Connections = {}, Jobs = Jobs.new(),
        Options = table.clone(Config.Options), Adapter = PetSim99.new(), Care = PetCare.new(),
        Ready = false, Failures = {}, NextAt = {},
        State = { Status = "Idle — run the compatibility check manually", Target = "None", EquippedPets = 0,
            Farmed = 0, CollectedOrbs = 0, CollectedLootbags = 0, LastError = "",
            CareStatus = "Pet tools idle — click Load pet tools", HatchRequests = 0, GoldRequests = 0, RainbowRequests = 0 },
    }, Runtime)
    self.Navigator = MachineNavigation.new(player, function(message)
        if not self.Alive then return end
        self.State.CareStatus = message
        self:Publish()
    end)
    self.Ui = Interface.mount({
        parent = parent, name = Config.Name, version = Config.Version, options = self.Options,
        onChange = function(key, value) return self:SetOption(key, value) end,
        onAction = function(action) return self:Action(action) end,
    })
    table.insert(self.Connections, player.CharacterAdded:Connect(function(character)
        for _, key in ipairs({ "AutoFarm", "AutoCollectOrbs", "AutoCollectLootbags" }) do self.Jobs:cancel(key) end
        self.Jobs:cancel("care")
        self.Navigator:Stop()
        self:StopNavigation()
        self.LastAssignment = nil
        self.NextAt = {}
        self:RestoreMovement()
        self.Jobs:cancel("movement")
        self.Jobs:start("movement", 10, function()
            return character:WaitForChild("Humanoid", 8)
        end, function(ok, humanoid)
            if ok and humanoid and self.Options.MovementEnabled then self:ApplyMovement(humanoid) end
        end)
    end))
    table.insert(self.Connections, player.Idled:Connect(function()
        if not self.Options.AntiIdle then return end
        local ok, message = pcall(function()
            local user = game:GetService("VirtualUser")
            user:CaptureController()
            user:ClickButton2(Vector2.new(0, 0))
        end)
        if not ok then
            self.Options.AntiIdle = false
            self.AntiIdleUnavailable = true
            self.State.LastError = "Idle input unsupported: " .. tostring(message)
            self:Publish()
        end
    end))
    table.insert(self.Connections, game:GetService("TeleportService").TeleportInitFailed:Connect(function(who, _, message)
        if who == player and self.Alive then
            self.State.LastError = "Rejoin failed: " .. tostring(message)
            self:Publish()
        end
    end))
    self:Publish()
    self.Pulse = task.spawn(function()
        while self.Alive do
            local ok, message = pcall(function()
                self.Jobs:tick()
                self:Step()
            end)
            if not ok then
                self:StopAll()
                self.State.LastError = "Scheduler stopped: " .. tostring(message)
                self:Publish()
            end
            task.wait(0.25)
        end
    end)
    return self
end

function Runtime:StopNavigation()
    local humanoid = self.Navigating
    self.Navigating = nil
    local root = self.Player.Character and self.Player.Character:FindFirstChild("HumanoidRootPart")
    if humanoid and humanoid.Parent and root then
        pcall(function() humanoid:MoveTo(root.Position) end)
    end
end

function Runtime:FeatureResult(key, ok, result)
    if ok then
        self.Failures[key] = 0
        if type(result) == "table" then
            for field, value in pairs(result) do self.State[field] = value end
        end
    else
        self.Failures[key] = (self.Failures[key] or 0) + 1
        self.State.LastError = key .. ": " .. tostring(result)
        if self.Adapter.Supported.AutoFarm == false then
            self.Ready = false
            for _, feature in ipairs({ "AutoFarm", "AutoCollectOrbs", "AutoCollectLootbags" }) do
                self.Options[feature] = false
                self.Jobs:cancel(feature)
            end
            self:StopNavigation()
            self.State.Status = "Protocol rejected — reconnect required; see Status."
            self:Publish()
            return
        end
        self.NextAt[key] = os.clock() + math.min(8, 2 ^ self.Failures[key])
        if self.Failures[key] >= Config.RetryLimit then
            self.Options[key] = false
            self.State.Status = key .. " stopped after repeated errors; see Status."
            if key == "AutoFarm" then self:StopNavigation() end
        end
    end
    self:Publish()
end

function Runtime:PrepareCare()
    for _, key in ipairs({ "AutoHatch", "AutoGold", "AutoRainbow" }) do self.Options[key] = false end
    self.Jobs:cancel("care")
    self.Navigator:Stop()
    local started = self.Jobs:start("care", Config.RequestTimeout, function(activeJob)
        return self.Care:Connect(activeJob)
    end, function(ok, result)
        local loaded = ok and (self.Care.Supported.AutoHatch or self.Care.Supported.AutoGold or self.Care.Supported.AutoRainbow)
        self.State.CareStatus = if loaded then self.Care.Reason else "Pet tools unavailable: " .. tostring(self.Care.Reason)
        self.State.LastError = if loaded then "" else (if ok then tostring(self.Care.Reason) else tostring(result))
            .. " [Pet stage: " .. tostring(self.Care._phase or "unknown") .. "]"
        self:Publish()
    end)
    if not started then return false, "A previous pet operation is still returning; no new request sent." end
    self:Publish()
    return true
end

function Runtime:LivingCharacter()
    local character = self.Player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not character or not character.Parent or not humanoid or humanoid.Parent ~= character
        or type(humanoid.Health) ~= "number" or not (humanoid.Health > 0)
        or not root or root.Parent ~= character then return nil end
    return character, humanoid, root
end

function Runtime:StartCare(key, manual)
    if not self.Alive then return false, "Suite unloaded." end
    if not self.Care.Supported[key] then return false, self.Care.Reason end
    local character, humanoid, root = self:LivingCharacter()
    if not character then return false, "Wait for a living character before using pet tools." end
    local egg, mode, species = self.Options.EggName, self.Options.HatchMode, self.Options.ConversionSpecies
    local travel = if key == "AutoHatch" then self.Options.EggTravelMode == "Walk" else self.Options.MachineTravelMode == "Walk"
    local timeout = Config.RequestTimeout + (if travel then Config.TravelTimeout else 0)
    local proximityLost = false
    local started = self.Jobs:start("care", timeout, function(activeJob)
        self.CareMutation = activeJob
        local arrivalGuard
        local function current()
            if not self.Alive or not activeJob() or not (manual or self.Options[key]) then return false end
            local liveCharacter, liveHumanoid, liveRoot = self:LivingCharacter()
            if liveCharacter ~= character or liveHumanoid ~= humanoid or liveRoot ~= root then return false end
            if arrivalGuard and not arrivalGuard() then proximityLost = true; return false end
            return true
        end
        if key == "AutoHatch" then
            if not self.Care:CanHatch(egg, mode, current) or not current() then return 0 end
            if travel then
                local target = self.Care:GetEggTarget(egg, current)
                if not target or not current() then return 0 end
                self.MachineJourney = activeJob
                self.Jobs:cancel("AutoFarm")
                self:StopNavigation()
                local reached, guard = self.Navigator:ApproachEgg(target, current)
                if not reached or not current() then return 0 end
                if type(guard) ~= "function" then error("Egg arrival could not be guarded; no purchase sent.", 0) end
                arrivalGuard = guard
                if not current() then return 0 end
                local arrivedTarget = self.Care:GetEggTarget(egg, current)
                if not current() then return 0 end
                if arrivedTarget ~= target then error("Selected egg changed while approaching; no purchase sent.", 0) end
            end
            return self.Care:Hatch(egg, mode, current)
        end
        local variant = if key == "AutoGold" then "Gold" else "Rainbow"
        if not self.Care:CanConvert(variant, species, current) or not current() then return 0 end
        if travel then
            self.Jobs:cancel("AutoFarm")
            self:StopNavigation()
            local reached, guard = self.Navigator:Approach(variant, current)
            if not reached or not current() then return 0 end
            if type(guard) ~= "function" then error("Machine arrival could not be guarded; no conversion sent.", 0) end
            arrivalGuard = guard
        end
        if not current() then return 0 end
        return self.Care:Convert(variant, species, current)
    end, function(ok, result)
        self.State.CareStatus = if proximityLost then "Target changed or left range — operation stopped" else self.Care.Reason
        if not ok then
            self.Navigator:Stop()
            self.Options[key] = false
            self.State.LastError = key .. ": " .. tostring(result)
            self.State.CareStatus = "Pet operation stopped — see error"
        end
        self:Publish()
    end)
    if not started then return false, "A pet operation is still returning; no overlapping request sent." end
    return true
end

function Runtime:GoToMachine(variant, openMenu)
    if not self.Alive then return false, "Suite unloaded." end
    local character, humanoid, root = self:LivingCharacter()
    if not character then return false, "Wait for a living character before traveling." end
    self.Jobs:cancel("AutoFarm")
    self:StopNavigation()
    local started = self.Jobs:start("care", Config.TravelTimeout, function(activeJob)
        self.MachineJourney = activeJob
        local function current()
            if not self.Alive or not activeJob() then return false end
            local liveCharacter, liveHumanoid, liveRoot = self:LivingCharacter()
            return liveCharacter == character and liveHumanoid == humanoid and liveRoot == root
        end
        if not self.Navigator:Approach(variant, current) or not current() then return false end
        if openMenu then self.Care:OpenMenu(variant) end
        return true
    end, function(ok, result)
        if not ok then
            self.Navigator:Stop()
            self.State.LastError = "Machine travel: " .. tostring(result)
            self.State.CareStatus = "Machine travel stopped — see error"
        elseif result then
            self.State.CareStatus = "Arrived at " .. variant .. " machine"
        end
        self:Publish()
    end)
    if not started then return false, "A pet operation is still returning; no overlapping journey started." end
    return true
end

function Runtime:GoToEgg()
    if not self.Alive then return false, "Suite unloaded." end
    local character, humanoid, root = self:LivingCharacter()
    if not character then return false, "Wait for a living character before traveling." end
    local egg = self.Options.EggName
    local started = self.Jobs:start("care", Config.RequestTimeout + Config.TravelTimeout, function(activeJob)
        self.MachineJourney = activeJob
        local function current()
            if not self.Alive or not activeJob() then return false end
            local liveCharacter, liveHumanoid, liveRoot = self:LivingCharacter()
            return liveCharacter == character and liveHumanoid == humanoid and liveRoot == root
        end
        local target = self.Care:GetEggTarget(egg, current)
        if not target or not current() then return false end
        self.Jobs:cancel("AutoFarm")
        self:StopNavigation()
        return self.Navigator:ApproachEgg(target, current)
    end, function(ok, result)
        if not ok then
            self.Navigator:Stop()
            self.State.LastError = "Egg travel: " .. tostring(result)
            self.State.CareStatus = "Egg travel stopped — see error"
        elseif result then self.State.CareStatus = "Arrived at selected egg" end
        self:Publish()
    end)
    if not started then return false, "A pet operation is still returning; no overlapping journey started." end
    return true
end

function Runtime:StepCare()
    if not self.Alive then return end
    if not self:LivingCharacter() then
        if (self.CareMutation and self.CareMutation()) or (self.MachineJourney and self.MachineJourney()) then
            self.Jobs:cancel("care")
            self.Navigator:Stop()
        end
        if self.Options.AutoHatch or self.Options.AutoGold or self.Options.AutoRainbow then
            self.State.CareStatus = "Waiting for a living character — automatic pet actions paused"
            self:Publish()
        end
        return
    end
    local now = os.clock()
    local features = { "AutoRainbow", "AutoGold", "AutoHatch" }
    local cursor = self.CareCursor or 1
    for offset = 0, #features - 1 do
        local index = (cursor + offset - 1) % #features + 1
        local key = features[index]
        if self.Options[key] and not self.Jobs:busy("care") and now >= (self.NextAt[key] or 0) then
            local interval = if key == "AutoHatch" then self.Options.HatchInterval else self.Options.ConversionInterval
            self.NextAt[key] = now + interval
            local started, reason = self:StartCare(key, false)
            if not started then
                self.Options[key] = false
                self.State.LastError = reason
                self:Publish()
            end
            self.CareCursor = index % #features + 1
            return
        end
    end
end

function Runtime:Step()
    self:StepCare()
    if self.Jobs:busy("care") and (self.Options.MachineTravelMode == "Walk"
        or (self.MachineJourney and self.MachineJourney())) then
        self.Jobs:cancel("AutoFarm")
        self:StopNavigation()
        self:Publish()
        return
    end
    if not self.Ready then
        local now = os.clock()
        if now >= (self.NextPublish or 0) and (self.Jobs:busy("connect") or self.Jobs:busy("care")) then
            self.NextPublish = now + 1
            self:Publish()
        end
        return
    end
    local now = os.clock()
    local character = self.Player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health <= 0 then
        for _, key in ipairs({ "AutoFarm", "AutoCollectOrbs", "AutoCollectLootbags" }) do self.Jobs:cancel(key) end
        self:StopNavigation()
        self.LastAssignment = nil
        if self.Options.AutoFarm then self.State.Status = "Waiting for a living character..." end
        self:Publish()
        return
    end
    if self.Options.AutoFarm and not self.Jobs:busy("AutoFarm") and now >= (self.NextAt.AutoFarm or 0) then
        self.NextAt.AutoFarm = now + self.Options.FarmInterval
        self.Jobs:start("AutoFarm", Config.FarmTimeout, function(activeJob)
            local snapshot = self.Adapter:Snapshot(activeJob)
            if not activeJob() or self.Player.Character ~= character or not character.Parent or not root.Parent or humanoid.Health <= 0 then
                return { Status = "Waiting for the current character..." }
            end
            if self.Options.FarmMode ~= "Nearest" and not snapshot.HealthKnown then
                error("This coin response has no reliable health data. Select Nearest priority.")
            end
            self.State.EquippedPets = #snapshot.Pets
            local target = Policy.select(snapshot.Candidates, self.Options)
            if not target then
                self:StopNavigation()
                return { Status = "No loaded targets match radius/area/name filters.", Target = "None" }
            end
            local title = target.name .. " / " .. target.area
            if #snapshot.Pets == 0 then
                self:StopNavigation()
                return { Status = "Equip pets in-game to start farming.", Target = title }
            end
            if self.Options.WalkToTarget and target.distance > 20 then
                self.Navigating = humanoid
                humanoid:MoveTo(target.position)
                return { Status = "Walking toward target...", Target = title }
            end
            self:StopNavigation()
            local sorted = {}
            for _, uid in ipairs(snapshot.Pets) do table.insert(sorted, tostring(uid)) end
            table.sort(sorted)
            local signature = table.concat(sorted, "|")
            local last = self.LastAssignment
            if last and last.Id == target.id and last.Pets == signature and now - last.Time < Config.ReassignSeconds then
                return { Status = "Recent farm requests; watching target.", Target = title }
            end
            local count = self.Adapter:Assign(target, snapshot.Pets, function()
                return activeJob() and self.Alive and self.Options.AutoFarm and self.Player.Character == character
                    and character.Parent ~= nil and root.Parent ~= nil and humanoid.Parent ~= nil and humanoid.Health > 0
            end)
            if count > 0 then
                self.LastAssignment = { Id = target.id, Pets = signature, Time = os.clock() }
            end
            return { Status = if count > 0 then "Farm requests sent; waiting for game response." else self.Adapter.Reason, Target = title,
                Farmed = self.State.Farmed + count }
        end, function(ok, result) self:FeatureResult("AutoFarm", ok, result) end)
    end
    for _, pair in ipairs({ { "AutoCollectOrbs", "orbs", "CollectedOrbs" },
        { "AutoCollectLootbags", "lootbags", "CollectedLootbags" } }) do
        local key, kind, field = pair[1], pair[2], pair[3]
        if self.Options[key] and not self.Jobs:busy(key) and now >= (self.NextAt[key] or 0) then
            self.NextAt[key] = now + 1
            self.Jobs:start(key, Config.RequestTimeout, function(activeJob)
                local count = self.Adapter:Collect(kind, self.Options.Radius, function()
                    return activeJob() and self.Alive and self.Options[key] and self.Player.Character == character
                        and character.Parent ~= nil and root.Parent ~= nil and humanoid.Parent ~= nil and humanoid.Health > 0
                end)
                return { [field] = self.State[field] + count }
            end, function(ok, result) self:FeatureResult(key, ok, result) end)
        end
    end
    if now >= (self.NextPublish or 0) then
        for _, key in ipairs({ "AutoFarm", "AutoCollectOrbs", "AutoCollectLootbags" }) do
            if self.Options[key] and self.Jobs:blocked(key) then
                self.State.Status = "Waiting for a canceled request to finish; no retry sent."
                break
            end
        end
        self.NextPublish = now + 1
        self:Publish()
    end
end

function Runtime:Publish()
    if not self.Alive then return end
    self.State.Options = table.clone(self.Options)
    self.State.WorkerStatus = self.Jobs:summary()
    self.State.ProbeStage = self.Adapter._phase or "not started"
    self.State.CareStage = self.Care._phase or "not started"
    self.State.Supported = table.clone(self.Adapter.Supported)
    for key, supported in pairs(self.Care.Supported) do self.State.Supported[key] = supported end
    for field, count in pairs(self.Care.Counts) do self.State[field] = count end
    self.State.Supported.AntiIdle = not self.AntiIdleUnavailable
    self.State.Capabilities = self.Adapter.Reason
        .. "\nNative Roblox UI; no external UI loader or hooks required."
        .. "\nIdle input and clipboard are tested only when used.\n" .. self.Care.Reason
    self.Ui:Update(self.State)
end

function Runtime:RestoreMovement()
    local saved = self.Movement
    self.Movement = nil
    if saved and saved.Humanoid.Parent then
        pcall(function()
            saved.Humanoid.WalkSpeed = saved.WalkSpeed
            saved.Humanoid.JumpPower = saved.JumpPower
            saved.Humanoid.JumpHeight = saved.JumpHeight
        end)
    end
end

function Runtime:ApplyMovement(humanoid)
    humanoid = humanoid or (self.Player.Character and self.Player.Character:FindFirstChildOfClass("Humanoid"))
    if not humanoid then return end
    if not self.Movement or self.Movement.Humanoid ~= humanoid then
        self:RestoreMovement()
        self.Movement = { Humanoid = humanoid, WalkSpeed = humanoid.WalkSpeed,
            JumpPower = humanoid.JumpPower, JumpHeight = humanoid.JumpHeight }
    end
    humanoid.WalkSpeed = self.Options.WalkSpeed
    if humanoid.UseJumpPower then
        humanoid.JumpPower = self.Options.JumpPower
    else
        humanoid.JumpHeight = self.Options.JumpPower ^ 2 / (2 * math.max(workspace.Gravity, 1))
    end
end

function Runtime:SetLighting(enabled)
    if enabled then
        if not self.Lighting then
            self.Lighting = {}
            for _, key in ipairs({ "Brightness", "ClockTime", "FogEnd", "GlobalShadows", "Ambient", "OutdoorAmbient" }) do
                self.Lighting[key] = Lighting[key]
            end
        end
        Lighting.Brightness = 2
        Lighting.ClockTime = 14
        Lighting.FogEnd = 100000
        Lighting.GlobalShadows = false
        Lighting.Ambient = Color3.fromRGB(180, 180, 180)
        Lighting.OutdoorAmbient = Color3.fromRGB(180, 180, 180)
    elseif self.Lighting then
        for key, value in pairs(self.Lighting) do pcall(function() Lighting[key] = value end) end
        self.Lighting = nil
    end
end

function Runtime:SetOption(key, value)
    if not self.Alive then return false, "Suite is unloaded." end
    local parsed, reason = Policy.option(key, value)
    if parsed == nil then return false, reason end
    if parsed == true and self.Adapter.Supported[key] == false then
        return false, self.Adapter.Reason
    end
    if parsed == true and self.Care.Supported[key] == false then return false, self.Care.Reason end
    if key == "AntiIdle" and parsed and self.AntiIdleUnavailable then
        return false, "This executor rejected idle input in this session."
    end
    local previous = self.Options[key]
    self.Options[key] = parsed
    if type(parsed) == "boolean" then
        if not parsed then
            self.Jobs:cancel(key)
            if key == "AutoHatch" or key == "AutoGold" or key == "AutoRainbow" then
                self.Jobs:cancel("care")
                self.Navigator:Stop()
            end
            if key == "AutoFarm" or key == "WalkToTarget" then self:StopNavigation() end
        else
            self.Failures[key] = 0
            self.NextAt[key] = 0
        end
    end
    if key == "EggName" or key == "HatchMode" or key == "ConversionSpecies" or key == "MachineTravelMode" or key == "EggTravelMode" then
        self.Jobs:cancel("care")
        self.Navigator:Stop()
    end
    if key == "AutoFarm" or key == "FarmMode" or key == "Area" or key == "NameFilter" or key == "Radius" then
        self.Jobs:cancel("AutoFarm")
        self:StopNavigation()
        self.LastAssignment = nil
        self.Failures.AutoFarm = 0
        self.NextAt.AutoFarm = 0
    end
    local ok, message = pcall(function()
        if key == "MovementEnabled" then
            if parsed then self:ApplyMovement() else self:RestoreMovement() end
        elseif key == "WalkSpeed" or key == "JumpPower" then
            if self.Options.MovementEnabled then self:ApplyMovement() end
        elseif key == "Fullbright" then
            self:SetLighting(parsed)
        end
    end)
    if not ok then
        self.Options[key] = previous
        if key == "MovementEnabled" or key == "WalkSpeed" or key == "JumpPower" then
            self.Options.MovementEnabled = false
            self:RestoreMovement()
        elseif key == "Fullbright" then
            self.Options.Fullbright = false
            self:SetLighting(false)
        end
        self.State.LastError = tostring(message)
        self:Publish()
        return false, tostring(message)
    end
    self:Publish()
    return true
end

function Runtime:StopAll()
    self.Jobs:cancelAll()
    self.Navigator:Stop()
    self:StopNavigation()
    self.LastAssignment = nil
    self.NextAt = {}
    for key, value in pairs(self.Options) do
        if type(value) == "boolean" then self.Options[key] = false end
    end
    self:RestoreMovement()
    self:SetLighting(false)
    self.State.Status = "Stopped — all automation disabled"
    self.State.CareStatus = "Pet automation stopped"
    self:Publish()
end

function Runtime:InspectEnvironment()
    if not self.Alive then return false, "Suite unloaded." end
    if self.Jobs:busy("connect") then
        return false, "A compatibility check is still active. No parallel preflight was started."
    end
    local ok, ready, message = pcall(function() return self.Adapter:Inspect() end)
    if not ok then
        message = tostring(ready)
        ready = false
    end
    self.State.Status = if ready then "Local preflight passed — protocol not tested" else "Local preflight needs attention"
    self.State.LastError = if ready then "" else tostring(message)
    self:Publish()
    return ready, message
end

function Runtime:Reconnect()
    self:StopAll()
    self.Ready = false
    self.Adapter.Supported = { AutoFarm = false, AutoCollectOrbs = false, AutoCollectLootbags = false, WalkToTarget = false }
    if type(self.Adapter.Inspect) == "function" then
        local ok, ready, message = pcall(function() return self.Adapter:Inspect() end)
        if not ok or not ready then
            self.State.Status = "Local preflight failed; no network request sent"
            self.State.LastError = if ok then tostring(message) else tostring(ready)
            self:Publish()
            return false, self.State.LastError
        end
    end
    self.State.Status = "Checking Classic Event protocol..."
    self:Publish()
    local started = self.Jobs:start("connect", Config.RequestTimeout, function(activeJob)
        return self.Adapter:Connect(activeJob)
    end, function(ok, message)
        self.Ready = ok and self.Adapter.Supported.AutoFarm == true
        self.State.Status = if self.Ready then "Protocol probe passed — enable a feature to test in game" else "Compatibility probe failed — see Status"
        self.State.LastError = if self.Ready then "" elseif not ok then tostring(message) .. " [Probe stage: " .. tostring(self.Adapter._phase or "unknown") .. "]" else self.Adapter.Reason
        self:Publish()
    end)
    if not started then
        self.State.Status = "Previous compatibility check is still returning; no new check sent."
        self:Publish()
        return false, self.State.Status
    end
    return true
end

function Runtime:Diagnostics()
    return table.concat({
        Config.Name .. " v" .. Config.Version,
        "Startup makes no game-module or network probe. The compatibility check is manual.",
        "Current PlaceId: " .. tostring(game.PlaceId) .. "; UniverseId: " .. tostring(game.GameId),
        "Current probe stage: " .. tostring(self.Adapter._phase or "not started"),
        "Current pet-tools stage: " .. tostring(self.Care._phase or "not started"),
        "Navigation stage: " .. tostring(self.Navigator.Stage or "not started"),
        "Pet operation status: " .. tostring(self.State.CareStatus),
        "Active workers:\n" .. self.Jobs:summary(),
        self.Adapter.Report,
        self.Care.Report,
        "Options: " .. HttpService:JSONEncode(self.Options),
        "Last error: " .. tostring(self.State.LastError),
        "Counters represent requests, not confirmed rewards. No credentials or inventory transfer is performed.",
    }, "\n")
end

function Runtime:Action(action)
    if action == "StopAll" then self:StopAll()
    elseif action == "Reconnect" then return self:Reconnect()
    elseif action == "InspectEnvironment" then return self:InspectEnvironment()
    elseif action == "PrepareCare" then return self:PrepareCare()
    elseif action == "NextEgg" or action == "NextSpecies" then
        local key = if action == "NextEgg" then "EggName" else "ConversionSpecies"
        local value, caption = self.Care:NextChoice(if action == "NextEgg" then "Egg" else "Species", self.Options[key])
        local accepted, reason = self:SetOption(key, value)
        if not accepted then return false, reason end
        self.State.CareStatus = "Selected " .. caption
        self:Publish()
    elseif action == "HatchOnce" then return self:StartCare("AutoHatch", true)
    elseif action == "GoSelectedEgg" then return self:GoToEgg()
    elseif action == "GoldOnce" then return self:StartCare("AutoGold", true)
    elseif action == "RainbowOnce" then return self:StartCare("AutoRainbow", true)
    elseif action == "OpenEggMenu" then return self.Care:OpenMenu("Egg")
    elseif action == "GoGoldMachine" then return self:GoToMachine("Gold", false)
    elseif action == "GoRainbowMachine" then return self:GoToMachine("Rainbow", false)
    elseif action == "OpenGoldMenu" then
        if self.Options.MachineTravelMode == "Walk" then return self:GoToMachine("Gold", true) end
        return self.Care:OpenMenu("Gold")
    elseif action == "OpenRainbowMenu" then
        if self.Options.MachineTravelMode == "Walk" then return self:GoToMachine("Rainbow", true) end
        return self.Care:OpenMenu("Rainbow")
    elseif action == "OpenInventory" then return self.Care:OpenMenu("Inventory")
    elseif action == "ClearError" then self.State.LastError = ""; self:Publish()
    elseif action == "ResetMovement" then return self:SetOption("MovementEnabled", false)
    elseif action == "Unload" then self:Destroy()
    elseif action == "Rejoin" then
        self:StopAll()
        local ok, message = pcall(function()
            game:GetService("TeleportService"):Teleport(game.PlaceId, self.Player)
        end)
        if not ok then return false, tostring(message) end
    elseif action == "CopyDiagnostics" then
        local report = self:Diagnostics()
        local copy = setclipboard or toclipboard
        if type(copy) == "function" then
            local ok, message = pcall(copy, report)
            if ok then return true end
            self.State.LastError = "Clipboard failed: " .. tostring(message)
        end
        print(report)
        self:Publish()
        return false, "Clipboard unavailable; diagnostics printed to the console."
    else return false, "Unknown action." end
    return true
end

function Runtime:Destroy()
    if not self.Alive then return end
    self:StopAll()
    self.Alive = false
    if self.Pulse then pcall(task.cancel, self.Pulse) end
    for _, connection in ipairs(self.Connections) do connection:Disconnect() end
    self.Adapter:Destroy()
    self.Care:Destroy()
    self.Ui:Destroy()
    if self.OnDestroy then self.OnDestroy() end
end

return Runtime
end
end

do
__factories["init.client.luau"] = function(__require)
--!nocheck
local Runtime = __require("Runtime.luau")

if not game:IsLoaded() then game.Loaded:Wait() end
local player = game:GetService("Players").LocalPlayer
assert(player, "Run the suite in a Roblox client, after joining the Classic Event.")
local parent = player:WaitForChild("PlayerGui", 15)
assert(parent, "PlayerGui was not available within 15 seconds.")

-- BindableEvent works in both Studio and executor environments, without getgenv.
-- A repeated run tells the prior session to restore changes before replacing it.
local markerName = "PetSim99AutomationSuiteSession"
-- Recognize older releases so renaming never leaves two suites running.
for _, name in ipairs({ markerName, "PetSimAutomationSession" }) do
    local previous = parent:FindFirstChild(name)
    if previous then
        if not previous:IsA("BindableEvent") then
            error("A conflicting session marker already exists; unload it first.")
        end
        previous:Fire()
        local deadline = os.clock() + 3
        while previous.Parent and os.clock() < deadline do task.wait() end
        assert(not previous.Parent, "Previous suite did not unload; remove its session before retrying.")
    end
end
local marker = Instance.new("BindableEvent")
marker.Name = markerName
marker.Parent = parent
local ok, runtime = pcall(Runtime.new, player, parent)
if not ok then
    marker:Destroy()
    error(runtime)
end
local connection
connection = marker.Event:Connect(function()
    runtime:Destroy()
end)
runtime.OnDestroy = function()
    connection:Disconnect()
    marker:Destroy()
end
end
end

local __cache = {}
local __loaded = {}
local __loading = {}
local function __require(name)
    if __loaded[name] then
        return __cache[name]
    end
    if __loading[name] then
        error("Circular module dependency: " .. name, 2)
    end
    local factory = __factories[name]
    if not factory then
        error("Unknown bundled module: " .. name, 2)
    end
    __loading[name] = true
    local ok, result = pcall(factory, __require)
    __loading[name] = nil
    if not ok then
        error("Module " .. name .. " failed: " .. tostring(result), 2)
    end
    __loaded[name] = true
    __cache[name] = result
    return result
end

return __require("init.client.luau")
